/**
 * Builds one icon component.
 *
 * <p>The body is injected as raw markup because these SVGs use hyphenated SVG
 * attributes (stroke-width, stroke-linecap) that JSX will not accept. It is safe
 * here in a way it would not be elsewhere: every string is a build-time constant
 * generated from the table above, and no value from a user or a server ever
 * reaches it.
 *
 * <p>width/height are attributes rather than styles so a Tailwind size class
 * (h-5 w-5) still wins, which is how every call site sizes its icon.
 */
function icon(name: string, displayName: string) {
  const Icon = ({ className, ...rest }: SVGProps<SVGSVGElement>) => (
    <svg
      viewBox="0 0 24 24"
      width={24}
      height={24}
      className={className}
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: ICONS[name] }}
      {...rest}
    />
  );
  Icon.displayName = displayName;
  return Icon;
}

